// ===========================================================================
//  NHẬP 7 THÔNG SỐ (sửa rồi bấm Execute workflow)
// ===========================================================================
const NAV       = 186922;  // Tài sản ròng - ĐỒNG (copy ĐÚNG số NAV từ app, vd app hiện 186,922 = 186.922đ)
const TICKER    = 'BID';   // Mã
const ENTRY     = 42.0;    // Giá dự định VÀO - NGHÌN đồng (42 = 42.000đ)
const STOP      = 39.0;    // Giá CẮT LỖ - nghìn đồng (BẮT BUỘC, < giá vào)
const TARGET    = 46.0;    // Giá MỤC TIÊU - nghìn đồng (0 = bỏ qua R:R)
const RISK_PCT  = 1.5;     // % tài khoản chấp nhận MẤT mỗi lệnh (khuyên 1-2%)
const MAX_POS_PCT = 20;    // Trần % NAV cho 1 vị thế (chống tất tay)
// ===========================================================================

const fmtM = (d) => (d / 1e6).toFixed(d < 1e7 ? 2 : 1) + ' triệu';   // d = đồng
const fmtP = (k) => Math.round(k * 1000).toLocaleString('vi-VN') + 'đ'; // k = nghìn đồng

let msg;
if (!(STOP < ENTRY)) {
  msg = '🧮 *POSITION SIZING — ' + TICKER + '*\n\n⚠️ *Lỗi nhập liệu*: Giá cắt lỗ (' + STOP + ') phải THẤP HƠN giá vào (' + ENTRY + '). '
      + 'Kỷ luật #1: không có cắt lỗ thì không tính khối lượng.';
} else {
  const entryD        = ENTRY * 1000;                // đồng/cổ phiếu
  const riskBudget    = NAV * RISK_PCT / 100;        // đồng được phép mất
  const riskPerShare  = (ENTRY - STOP) * 1000;       // đồng rủi ro / cổ phiếu
  const lotCost       = entryD * 100;                // giá 1 lô (100 cp)
  const sharesByRisk  = Math.floor(riskBudget / riskPerShare / 100) * 100;
  const sharesByCap   = Math.floor(NAV * MAX_POS_PCT / 100 / entryD / 100) * 100;
  const shares        = Math.max(0, Math.min(sharesByRisk, sharesByCap));
  const cappedByPos   = sharesByCap < sharesByRisk;

  const posVal      = shares * entryD;
  const posPct      = NAV > 0 ? posVal / NAV * 100 : 0;
  const realRisk    = shares * riskPerShare;
  const realRiskPct = NAV > 0 ? realRisk / NAV * 100 : 0;
  const rr          = TARGET > ENTRY ? (TARGET - ENTRY) / (ENTRY - STOP) : null;

  const L = [];
  L.push('🧮 *POSITION SIZING — ' + TICKER + '*');
  L.push('_Vào ' + fmtP(ENTRY) + ' · Cắt lỗ ' + fmtP(STOP) + (TARGET > 0 ? ' · Mục tiêu ' + fmtP(TARGET) : '') + '_');
  L.push('_NAV ' + fmtM(NAV) + ' · rủi ro cho phép ' + RISK_PCT + '%/lệnh_');
  L.push('');
  if (shares <= 0) {
    L.push('→ *Chưa đủ vốn cho lệnh này.*');
    L.push('   NAV ' + fmtM(NAV) + ' / rủi ro ' + RISK_PCT + '% chỉ cho mua < 1 lô.');
    L.push('   1 lô (100 cp) ' + TICKER + ' ở giá ' + fmtP(ENTRY) + ' ≈ *' + fmtM(lotCost) + '*.');
    L.push('   → Cần nạp thêm vốn, hoặc chọn mã giá thấp hơn.');
  } else {
    L.push('→ *MUA: ' + shares.toLocaleString('vi-VN') + ' cổ phiếu* (' + (shares / 100) + ' lô)');
    L.push('→ Giá trị vị thế: *' + fmtM(posVal) + '* (' + posPct.toFixed(1) + '% NAV)' + (cappedByPos ? ' _(chạm trần ' + MAX_POS_PCT + '%)_' : ''));
    L.push('→ Rủi ro thực nếu chạm cắt lỗ: *' + fmtM(realRisk) + '* (' + realRiskPct.toFixed(2) + '% NAV)');
    if (rr !== null) L.push('→ *R:R = ' + rr.toFixed(2) + '* — lãi kỳ vọng ' + rr.toFixed(2) + 'đ cho mỗi 1đ rủi ro');
  }
  L.push('');
  const W = [];
  if (RISK_PCT > 3) W.push('Rủi ro/lệnh ' + RISK_PCT + '% là CAO — khuyên 1-2%.');
  if (rr !== null && rr < 2 && shares > 0) W.push('R:R < 2 — lãi/rủi ro hơi mỏng. PTJ khuyên ≥2-3:1; cân nhắc chờ giá vào tốt hơn hoặc mục tiêu xa hơn.');
  if (cappedByPos && shares > 0) W.push('Vị thế bị giới hạn bởi trần ' + MAX_POS_PCT + '% NAV (chống tập trung 1 mã).');
  if (W.length) L.push('⚠️ ' + W.join('\n⚠️ '));
  L.push('');
  L.push('_Kỷ luật: định cắt lỗ TRƯỚC khi tính khối lượng · không trung bình giá xuống · KHÔNG phải khuyến nghị_');
  msg = L.join('\n');
}

return [{ json: { message: msg } }];
